from pathlib import Path
import json
O=Path(__file__).resolve().parent;R=O.parents[4]
p=O/'write_interactions.py';t=p.read_text();a=t.index('summary=');b=t.index("for part in ['a','b']:",a)
summary=[('Quantité,composition,persistance etcontexte précèdent le code ;N06 ajoute une morphologie précisée.','CH-CIM'),('Aucune incidenceN06directe ; le chiffreMRCglobal et lesbiopsies sélectionnées ne mesurent pas cetteprésentation.','CH-SGN-DEF'),('Filtre,réabsorption et surcharge produisent des profils différents ; la composition aide àles distinguer.','CH-PROT-MEC'),('Vérifiergravité,confirmer,caractériser puis établir cause/plan ; la répétition ne retarde pas uneurgence.','CH-PROT-REF'),('Conditionsderecueil,résultatsdatés,terrain,famille et produitspris sont des donnéesdiagnostiques.','INT-CKD-URINE'),('Pression,sédiment,fonction etalbumine éprouvent le caractèreisolé ; touteanomalie associée requalifie leprofil.','EU-PROT-WORKUP'),('Normalité,albuminurie,protéinurieclinique,syndromenéphrotique,MRC et morphologie sont des axesdistincts.','EU-PROT-DEF'),('Confirmerlerésultat,précisercomposition,durée,posture et anomaliesassociées,puis vérifier lapreuvemorphologique.','INT-CKD-URINE'),('Chaqueexamen doit répondre àunequestion ; la biopsie sert une décisionclinique,pas uncode.','INT-GN-GENERAL'),('La discordance albumine/protéinestotales ou ancienprofil/évolutionactuelle rouvre lediagnostic.','CH-PROT-MEC'),('Traiterune cause etunrisque établis ; recommandationssuisses etFIexactes limitent chaqueproduit.','CH-SGN-PEC'),('Suivre la trajectoire avecprélèvements comparables ; aucun marqueur seulneprouve laguérison.','INT-CKD-RISK'),('Décrire quantité,composition,persistance,contexte etplan ; casMEDINA sansstatutofficiel.','CH-PROFILES'),('Protéinurieisolée ne signifie niabsence derisque niindication automatique deN06/biopsie/traitement.','CH-CIM')]
t=t[:a]+'summary='+repr(summary)+'\n'+t[b:]
a=t.index('cases=');b=t.index('for i,(title,body,refs)',a)
cases=[('Après effort, confirmer avant de conclure','<p>Une personne asymptomatique présente des protéines à la bandelette après un exercice intense. Vérifier les conditions et confirmer par une mesure quantitative, de préférence au premier matin dans un contexte comparable. Une premièrepositivité ne prouve ni maladiepermanente ni morphologieN06.</p><p>Chez un adolescent, la disparition en décubitus peut orienter une orthostatique après confirmation du profil. Pression,sédiment etfonction doivent rester cohérents ; une anomalieassociée modifie la démarche.</p>',('EU-PROT-WORKUP','INT-CKD-URINE','CH-CIM')),('Le total et l’albumine racontent deux informations','<p>LePCR est nettement élevé mais l’ACR peu augmenté. La bandelette presque négative ne permet pas de conclure àl’absence demaladie : elle détecte surtout l’albumine. Rechercher une composante tubulaire oudesurcharge selon lecontexte et les examensappropriés.</p><p>La discordance ne donne pas seule une cause. Vérifier unités,prélèvement etrépétition puis orienter les investigations ; ne pas assimiler automatiquement toutes les protéines àune fuiteglomérulaire.</p>',('CH-PROT-METHOD','CH-PROT-MEC','EU-PROT-DEF')),('Une filtration conservée n’efface pas le dommage','<p>Une personne a un débit estiméà95mL/min/1,73m² et une albuminurie pathologique documentée depuis sixmois. Une filtrationG1 n’exclut pas uneMRC : la persistance du marqueur apporte une autre voie diagnostique.</p><p>Le diagnostic decause et le risque restent àpréciser. En l’absence de lésionmorphologique documentée,on ne déduit pas N06 du seul dosage ; lecodage suit le dossier etles exclusionsOFS.</p>',('INT-CKD-DEF','CH-CIM','CH-SGN-REF')),('Une recommandation de classe ne remplace pas uneFI','<p>Chez un adulte dont le débit est22mL/min/1,73m², une recommandation de classe évoque un inhibiteurSGLT2 dès20. LaFIForxiga consultée ne recommande pas l’introduction sous25. Ce produit ne se débute donc pas simplement en recopiant le seuil declasse.</p><p>Une poursuite après débutantérieur est une autre décision. Vérifier indication,volume,autresmédicaments et restrictions, notamment immunosuppresseur,greffe ou dialyse.</p>',('CH-SGN-PEC','INT-CKD-TX','FI-FORXIGA'))]
t=t[:a]+'cases='+repr(cases)+'\n'+t[b:]
a=t.index('quiz=');b=t.index("p=CH/'N06_b.html'",a)
quiz=[('Une bandelette négative exclut-elle toute protéinurie ?','Non,elle peut manquer une albuminurie modérée ou des protéinesnonalbuminiques.','Oui,le test mesure toutes les protéines.','La quantification etla composition répondent àune questiondifférente de ladétectionsemiquantitative.','CH-PROT-METHOD'),('Albumine60mg/L etcréatinine1g/L donnent quelACR ?','60mg/g.','60g/j.','Les litres s’annulent :60÷1=60mg/g ; ce n’est pas une collecte24hmesurée.','INT-CKD-URINE'),('Multiplier unrapportmg/mmol par10 donne-t-il une mesureexacte enmg/j ?','Non,c’est une estimationavec une excrétiondecréatinine présumée.','Oui,c’est une identitéd’unité.','La créatininurie quotidienne varie ; une collectechronométrée et unrapport sont des mesuresdifférentes.','CH-PROT-METHOD'),('Touteprotéinurieisolée impose-t-elle N06 etune biopsie ?','Non,la morphologie etles exclusionscomptent ; la biopsie répond àune questionclinique.','Oui,lecode décide dugeste.','ProtéinurieisoléeSAI,persistanteSAI,orthostatiqueSAI etgestationnelle ont des distinctionsOFS.','CH-CIM')]
t=t[:a]+'quiz='+repr(quiz)+'\n'+t[b:];p.write_text(t)
labels=['Anomalies glomérulaires mineures','Lésions glomérulaires segmentaires et focales','Glomérulonéphrite membraneuse diffuse','Glomérulonéphrite mésangio-proliférative diffuse','Glomérulonéphrite proliférative endocapillaire diffuse','Glomérulonéphrite mésangiocapillaire diffuse','Maladie à dépôt dense','Glomérulonéphrite diffuse en croissant','Autres modifications morphologiques','Type de modification morphologique non précisé']
annex='''from lesson_helpers import *
labels=LABELS
body='<p>N06 porte une exigence de lésionmorphologique précisée. Les suffixes .0–.8 nécessitent normalement une preuve tissulaire ; les dixentrées du modificateur commun sont reproduites ci-dessous. Le suffixe.9 proposé ne transforme pas une simple bandelette positive enN06 et ne supprime pas les conditions de catégorie. Le choix final suit le dossier et les règles applicables.</p>'+table(['Sous-code','Libellé morphologiqueOFS'],[['N06.'+str(i),x] for i,x in enumerate(labels)])+'<p>Exclusions : protéinurie deBenceJones,isoléeSAI ouSAI R80 ; orthostatiqueSAI N39.2 ; persistanteSAI N39.1 ; gestationnelleO12.1. L’inclusion vise les présentationsisolée/orthostatique/persistante avec morphologie précisée. Il ne faut jamais pratiquer une biopsie dans le seul but de remplir uncode ; la cause et la décisionclinique précèdent la nomenclature.</p>'
p=CH/'N06_b.html';txt=p.read_text();end=txt.rfind('</div></div>');assert end>0;p.write_text(txt[:end]+sec('annexe-cim','Après la conclusion clinique : sous-codes morphologiques',body,('CH-CIM',))+txt[end:])
'''.replace('LABELS',repr(labels));(O/'add_annex.py').write_text(annex)
(R/'glossary/n06.py').write_text('''from cardio_1 import a,G
# N06 — ajouts conditionnels, aucun ancien glossaire modifié.
if 'ACR' not in G:
    a('ACR',[('A','Albumine'),('CR','Créatinine')],'Rapport albumine/créatinine urinaire','<p>Quantifie l’albumine rapportée àla créatinine dumême prélèvement ; unitéet conditions visibles. Distinct desprotéinestotales et d’unecollecte24hmesurée.</p>','n06-calcul-ratio')
if 'RPC' not in G:
    a('RPC',[('P','Protéines'),('CR','Créatinine')],'Rapport protéines/créatinine urinaire','<p>Quantifie lesprotéinestotales rapportées àla créatinine ; le contexte distingue cette abréviation de la technique d’amplificationmoléculaire.</p>','n06-exp-8')
''')
p=R/'chapters.json';j=json.loads(p.read_text());assert not any(x['code']=='N06' for x in j);j.append(dict(code='N06',title='Protéinurie isolée avec lésions morphologiques précisées',covers=['N06'],wave=4,integrated=True,added='2026-11-02'));p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
